import { renderSlot } from 'vue'
import ElTooltip from '@element-plus/components/tooltip'

import type { FunctionalComponent } from 'vue'
import type { TableV2HeaderCell } from '../header-cell'

const HeaderCell: FunctionalComponent<TableV2HeaderCell> = (
  props,
  { slots }
) => {
  const title = props.column?.title ?? ''

  return renderSlot(slots, 'default', props, () => [
    <ElTooltip
      content={title}
      disabled={!title || !!props.column?.hoverTip}
      effect="light"
      placement="top-start"
      popperClass="text-overflow-tooltip"
    >
      <div class={props.class}>{title}</div>
    </ElTooltip>,
  ])
}

HeaderCell.displayName = 'ElTableV2HeaderCell'
HeaderCell.inheritAttrs = false

export default HeaderCell
